91: export function resolveModelPickerSelectedModel(input: {
92:   driverKind: ProviderDriverKind | undefined;
93:   model: string;
94:   options: ReadonlyArray<ModelEsque>;
95: }) {
96:   if (input.driverKind === "antigravity" && input.model === ANTIGRAVITY_DEFAULT_MODEL) {
97:     const availableModels = input.options.filter(
98:       (option) => option.slug !== ANTIGRAVITY_DEFAULT_MODEL && !option.isUnavailable,
99:     );
100:     return (
101:       availableModels.find((option) => option.aliases?.includes(ANTIGRAVITY_DEFAULT_MODEL)) ??
102:       availableModels.find((option) => option.isDefault)
103:     );
104:   }
105:   return input.options.find((option) => option.slug === input.model);
106: }
